CREATE OR REPLACE FUNCTION mem.storage_lifecycle_policy() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT '{"version":"file-lifecycle-20261019-v2","idle_days":14,"warm_uses":3,"tiers":["standard","archive"],"infrequent":"migrate_to_archive","special_default":"keep_standard","usage":"body_read/adopted/reused;distinct actor/client/version/event_key;maintenance excluded","legacy_clock":"original_last_use;original_creation_fallback;missing_pending;copy_excluded","deletion":"no_logical_file_or_history_deletion"}'::jsonb $$;